<?php
/**
 * Integration: leased embedding queue (Tier 1/Tier 2 contract) with SYNTHETIC TEST VECTORS.
 *
 * The vectors used here are deterministic pseudo-random unit vectors generated by the test.
 * They are NOT model output and prove only the storage/validation/lease protocol.
 *
 * @package SemanticSEO
 */

namespace SemanticSEO\Tests\Integration;

use SemanticSEO\Capabilities;
use SemanticSEO\Database\Db;
use SemanticSEO\Jobs\JobRepository;
use SemanticSEO\Jobs\JobRunner;
use SemanticSEO\Semantic\EmbeddingQueue;
use SemanticSEO\Semantic\EmbeddingRepository;
use SemanticSEO\Semantic\ModelProfile;
use SemanticSEO\Semantic\VectorMath;
use SemanticSEO\Services\Api;
use SemanticSEO\Support\Util;

/**
 * @group embeddings
 */
final class EmbeddingQueueTest extends TestCase {

	/**
	 * Deterministic unit vector (synthetic).
	 *
	 * @param string $seed Seed.
	 * @param int    $dim  Dimension.
	 * @return float[]
	 */
	private function synthetic( $seed, $dim ) {
		$v = array();
		for ( $i = 0; $i < $dim; $i++ ) {
			$v[] = ( hexdec( substr( md5( $seed . ':' . $i ), 0, 6 ) ) / 0xFFFFFF ) - 0.5;
		}
		return VectorMath::normalize( $v );
	}

	/**
	 * Inventories the corpus, starts an embedding job and becomes a worker.
	 *
	 * @return int Job ID.
	 */
	private function prepare() {
		$this->load_corpus();
		$this->run_full_pipeline();
		$job = JobRepository::create( 'embed', array(), $this->admin, 'test' );
		JobRunner::tick( 10, (int) $job['id'] );
		Capabilities::ensure_agent_roles();
		wp_set_current_user( self::factory()->user->create( array( 'role' => 'sseo_worker' ) ) );
		return (int) $job['id'];
	}

	public function test_claim_complete_and_vectors_feed_analysis() {
		$job_id  = $this->prepare();
		$profile = ModelProfile::active();
		$counts  = EmbeddingQueue::counts( $job_id );
		$this->assertGreaterThan( 0, $counts['pending'] );
		$stored = 0;
		do {
			$claim = Api::embedding_claim( array( 'limit' => 16 ) );
			if ( array() === $claim['items'] ) {
				break;
			}
			$this->assertSame( $profile['model_key'], $claim['profile']['model_key'] );
			$results = array();
			foreach ( $claim['items'] as $item ) {
				$this->assertNotSame( '', $item['text'] );
				$results[] = array(
					'queue_id' => $item['queue_id'],
					'vector'   => base64_encode( VectorMath::pack( $this->synthetic( $item['content_hash'], (int) $profile['dimension'] ) ) ), // phpcs:ignore
				);
			}
			$res     = Api::embedding_complete(
				array(
					'lease_token' => $claim['lease_token'],
					'model_key'   => $profile['model_key'],
					'results'     => $results,
					'source'      => 'worker',
				)
			);
			$stored += $res['stored'];
			$this->assertSame( array(), $res['rejected'] );
		} while ( true );
		$this->assertSame( array_sum( $counts ), $stored );
		$row = Db::row( 'SELECT * FROM {embeddings} LIMIT 1' );
		$this->assertSame( ModelProfile::MODEL_ID, $row['model_id'] );
		$this->assertSame( ModelProfile::REVISION, $row['revision'] );
		$this->assertSame( 'q4f16', $row['dtype'] );
		$this->assertSame( '1024', $row['dimension'] );
		$this->assertSame( 4096, strlen( $row['vector'] ) );

		// The job completes once nothing is pending.
		wp_set_current_user( $this->admin );
		JobRunner::tick( 10, $job_id );
		$this->assertSame( 'completed', JobRepository::get( $job_id )['status'] );

		// Semantic component now appears in pair features (never invented when vectors are missing).
		$vecs = EmbeddingRepository::summary_vectors( array( $this->doc( 'vi-pillar' ), $this->doc( 'vi-ngay' ) ), $profile['model_key'] );
		$this->assertCount( 2, $vecs );
		\SemanticSEO\Analysis\AnalysisRunner::analyze_document( $this->doc( 'vi-ngay' ), 999 );
		$f = Db::row( "SELECT evidence FROM {findings} WHERE type = 'link' AND document_id = %d AND run_id = 999 LIMIT 1", array( $this->doc( 'vi-ngay' ) ) );
		if ( null !== $f ) {
			$e = json_decode( $f['evidence'], true );
			$this->assertNotNull( $e['components']['semantic'] );
		}
	}

	public function test_invalid_vectors_replay_and_model_mismatch_rejected() {
		$this->prepare();
		$profile = ModelProfile::active();
		$claim   = Api::embedding_claim( array( 'limit' => 3 ) );
		$ids     = array_column( $claim['items'], 'queue_id' );
		$bad     = array(
			array(
				'queue_id' => $ids[0],
				'vector'   => array_fill( 0, 1024, 1.0 ),
			),
			array(
				'queue_id' => $ids[1],
				'vector'   => array_fill( 0, 10, 0.1 ),
			),
			array(
				'queue_id' => $ids[2],
				'vector'   => 'not-base64!!',
			),
		);
		$res     = Api::embedding_complete(
			array(
				'lease_token' => $claim['lease_token'],
				'model_key'   => $profile['model_key'],
				'results'     => $bad,
			)
		);
		$this->assertSame( 0, $res['stored'] );
		$this->assertCount( 3, $res['rejected'] );
		$this->assertSame( 0, (int) Db::value( 'SELECT COUNT(*) FROM {embeddings}' ) );

		$claim2 = Api::embedding_claim( array( 'limit' => 1 ) );
		$good   = array(
			array(
				'queue_id' => $claim2['items'][0]['queue_id'],
				'vector'   => $this->synthetic( 'x', 1024 ),
			),
		);
		$wrong  = Api::embedding_complete(
			array(
				'lease_token' => $claim2['lease_token'],
				'model_key'   => str_repeat( 'b', 40 ),
				'results'     => $good,
			)
		);
		$this->assertWPError( $wrong );
		$this->assertSame( 'sseo_model_mismatch', $wrong->get_error_code() );
		$ok = Api::embedding_complete(
			array(
				'lease_token' => $claim2['lease_token'],
				'model_key'   => $profile['model_key'],
				'results'     => $good,
			)
		);
		$this->assertSame( 1, $ok['stored'] );
		$replay = Api::embedding_complete(
			array(
				'lease_token' => $claim2['lease_token'],
				'model_key'   => $profile['model_key'],
				'results'     => $good,
			)
		);
		$this->assertSame( 0, $replay['stored'], 'Lease token is single-use.' );
	}

	public function test_expired_lease_and_changed_content() {
		$this->prepare();
		$profile = ModelProfile::active();
		$claim   = Api::embedding_claim( array( 'limit' => 2 ) );
		Db::query( 'UPDATE {queue} SET lease_expires = %s WHERE id IN (%d, %d)', array( Util::now( -10 ), $claim['items'][0]['queue_id'], $claim['items'][1]['queue_id'] ) );
		$res = Api::embedding_complete(
			array(
				'lease_token' => $claim['lease_token'],
				'model_key'   => $profile['model_key'],
				'results'     => array(
					array(
						'queue_id' => $claim['items'][0]['queue_id'],
						'vector'   => $this->synthetic( 'a', 1024 ),
					),
				),
			)
		);
		$this->assertSame( 0, $res['stored'] );
		$this->assertSame( 2, EmbeddingQueue::expire_leases() );

		$claim = Api::embedding_claim( array( 'limit' => 1 ) );
		$item  = $claim['items'][0];
		// The chunk text changes while the worker is busy.
		Db::query( 'UPDATE {chunks} SET content_hash = %s WHERE document_id = %d AND chunk_index = %d', array( str_repeat( 'c', 64 ), $item['document_id'], $item['chunk_index'] ) );
		$res = Api::embedding_complete(
			array(
				'lease_token' => $claim['lease_token'],
				'model_key'   => $profile['model_key'],
				'results'     => array(
					array(
						'queue_id' => $item['queue_id'],
						'vector'   => $this->synthetic( 'b', 1024 ),
					),
				),
			)
		);
		$this->assertSame( 'stale: content changed', $res['rejected'][0]['reason'] );
	}

	public function test_profile_change_requires_reindex() {
		$this->prepare();
		$before = ModelProfile::active()['model_key'];
		wp_set_current_user( $this->admin );
		\SemanticSEO\Settings::update( array( 'embedding_dimension' => 512 ) );
		$after = ModelProfile::active()['model_key'];
		$this->assertNotSame( $before, $after, 'Dimension is part of the model key: old vectors become ineligible.' );
		$this->assertSame( 0, EmbeddingQueue::counts()['pending'], 'Items queued for the old profile are not served for the new one.' );
	}

	public function test_release_all_mine_only_touches_the_callers_leases() {
		$this->prepare();
		$first  = Api::embedding_claim( array( 'limit' => 2 ) );
		$second = Api::embedding_claim( array( 'limit' => 2 ) );
		$this->assertCount( 2, $first['items'] );
		$this->assertCount( 2, $second['items'] );
		$other_worker = self::factory()->user->create( array( 'role' => 'sseo_worker' ) );
		$mine         = get_current_user_id();
		wp_set_current_user( $other_worker );
		$theirs = Api::embedding_claim( array( 'limit' => 2 ) );
		$this->assertCount( 2, $theirs['items'] );

		wp_set_current_user( $mine );
		$this->assertWPError( Api::embedding_release( array() ), 'Token or all_mine required.' );
		$res = Api::embedding_release(
			array(
				'all_mine' => true,
				'error'    => 'page closed',
			)
		);
		$this->assertSame( 4, $res['released'] );
		$this->assertSame( 2, (int) Db::value( "SELECT COUNT(*) FROM {queue} WHERE status = 'leased'" ), 'Other worker keeps its lease.' );
		$this->assertSame( 2, (int) Db::value( "SELECT COUNT(*) FROM {queue} WHERE status = 'leased' AND lease_owner = %d", array( $other_worker ) ) );
	}
}
